package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class NameVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property name of observed source ")
  void test_name_v_o_builder() {
    Assertions.assertFalse(NameVO.nullValue().getName().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(NameVO.tryFrom(null).getName().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", NameVO.from("one").getName().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> NameVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", NameVO.from("one").toString());
  }
}
